// ** Custom Components
import Avatar from '@components/avatar'

// ** Third Party Components
import axios from 'axios'
import { Fragment, useState } from 'react'
import { MoreVertical, Edit, FileText, Archive, Trash, Eye, Delete, FileMinus, Check, X } from 'react-feather'
import { useDispatch } from 'react-redux'

// ** Reactstrap Imports
import { Badge, UncontrolledDropdown, DropdownToggle, DropdownMenu, DropdownItem, Row, Col, Button, UncontrolledTooltip, Label, Input } from 'reactstrap'
import { exportRewardLinks } from '../../../../utility/Utils'
import { handleQuestion } from '../../sweetalert'
import ModalEditCampain from '../ModalEditCampainComponent'
import ModalShowCampaign from '../ModalShowCampainComponent'
import { deleteCampaign, getData, reloadTable, updatedCampaignInfoWithStatus } from './store'
// import ModalEditAgent from '../ModalEditAgentComponent'


export let data

// ** Get initial Data
axios.get('/api/datatables/initial-data').then(response => {
  data = response.data
})

// ** Expandable table component
const ExpandableTable = ({ data }) => {
  return (
    <div className='expandable-content p-2'>
      <p>
        <span className='fw-bold'>City:</span> {data.city}
      </p>
      <p>
        <span className='fw-bold'>Experience:</span> {data.experience}
      </p>
      <p className='m-0'>
        <span className='fw-bold'>Post:</span> {data.post}
      </p>
    </div>
  )
}

// ** Table Server Side Column
export const serverSideColumns = [
  {
    sortable: true,
    name: 'Mã chiến dịch',
    width: '200px',
    selector: row => row.id
  },
  {
    sortable: true,
    name: 'Tên chiến dịch',
    width: '300px',
    selector: row => row.name
  },
  {
    sortable: true,
    name: 'Ngày bắt đầu',
    width: '180px',
    selector: row => {
      const date = new Date(row.start_date)
      return `${(`0${date.getDate()}`).slice(-2)}-${(`0${date.getMonth() + 1}`).slice(-2)}-${date.getFullYear()} ${`0${date.getHours()}`.slice(-2)}:${`0${date.getMinutes()}`.slice(-2)}`
    }
  },
  {
    sortable: true,
    name: 'Ngày kết thúc',
    width: '180px',
    selector: row => {
      const date = new Date(row.end_date)
      return `${(`0${date.getDate()}`).slice(-2)}-${(`0${date.getMonth() + 1}`).slice(-2)}-${date.getFullYear()} ${`0${date.getHours()}`.slice(-2)}:${`0${date.getMinutes()}`.slice(-2)}`
    }
  },
  {
    sortable: true,
    name: 'Mô tả',
    width: '200px',
    selector: row => row.description
  },
  {
    name: 'Hành động',
    width: '240px',
    selector: (row) => {
      const [isShowModalShowCampaign, setIsShowModalShowCampaign] = useState(false)
      const [isShowModalEditCampaign, setIsShowModalEditCampaign] = useState(false)
      const dispatch = useDispatch()
      const handleDeleteCampaign = () => {
        handleQuestion("Bạn muốn tiếp tục?", "Thực hiện xóa chiến dịch sẽ không thể hoàn tác lại.", (isConfirmed) => {
          if (isConfirmed) {
            dispatch(
              deleteCampaign({
                id: row.id,
                reloadTable: () => dispatch(
                  reloadTable({
                    getData: (value) => dispatch(getData(value))
                  })
                )
              })
            )
          }
        })
      }
      const handleExportRewardLinks = () => {
        exportRewardLinks({
          used: false,
          entity: 'campaign',
          entity_id: row.id
        })
      }

      let date =  new Date()
      date = new Date(`${date.getFullYear()}-${`0${date.getMonth() + 1}`.slice(-2)}-${`0${date.getDate()}`.slice(-2)} ${`0${date.getHours()}`.slice(-2)}:${`0${date.getMinutes()}`.slice(-2)}`)
      let dateStart = new Date(row.start_date)
      dateStart = new Date(`${dateStart.getFullYear()}-${`0${dateStart.getMonth() + 1}`.slice(-2)}-${`0${dateStart.getDate()}`.slice(-2)} ${`0${dateStart.getHours()}`.slice(-2)}:${`0${dateStart.getMinutes()}`.slice(-2)}`)
      let endStart = new Date(row.end_date)
      endStart = new Date(`${endStart.getFullYear()}-${`0${endStart.getMonth() + 1}`.slice(-2)}-${`0${endStart.getDate()}`.slice(-2)} ${`0${endStart.getHours()}`.slice(-2)}:${`0${endStart.getMinutes()}`.slice(-2)}`)
     
      const isDisabled = (row.campaign_status_id === 2 || (dateStart.getTime() <= date.getTime() && date.getTime() <= endStart.getTime()))
      const isDisabled_2 = ((dateStart.getTime() <= date.getTime()))
      const CustomLabel = ({ htmlFor }) => {
        return (
          <Label className='form-check-label' htmlFor={htmlFor}>
            <span className='switch-icon-left'>
              <Check size={14} />
            </span>
            <span className='switch-icon-right'>
              <X size={14} />
            </span>
          </Label>
        )
      }

      const handleUpdateCampaignStatus = (checked, id) => {
        console.log("block", {
          id: row.id,
          name: row.name,
          description: row.description,
          campaign_status_id: (checked) ? 2 : 3,
          start_date: row.dateStart,
          end_date: row.dateEnd
        })
        handleQuestion("Bạn muốn tiếp tục?", "Thực hiện cập nhật trạng thái chiến dịch có thể ảnh hưởng đến khách hàng.", (isConfirmed) => {
          if (isConfirmed) {
            dispatch(
              updatedCampaignInfoWithStatus({
                id,
                name: row.name,
                description: row.description,
                status: (checked) ? 2 : 3,
                start_date: row.dateStart,
                end_date: row.dateEnd,
                reloadTable: () => dispatch(
                  reloadTable({
                    getData: (value) => dispatch(getData(value))
                  })
                )
              })
            )
          }
        })
      }

      return (
        <Fragment>
          {/* <ModalEditAgent isShow={isShowModalAgent} setIsShow={setIsShowModalAgent} data={row}/> */}
          <ModalShowCampaign isShow={isShowModalShowCampaign} setIsShow={setIsShowModalShowCampaign} data={row}/>
          <ModalEditCampain isShow={isShowModalEditCampaign} setIsShow={setIsShowModalEditCampaign} data={row} />
          <div className='d-flex'>
              <div> 
                <Button.Ripple id={`eye${row.id}`} className='btn-icon' color='flat-primary' onClick={() => setIsShowModalShowCampaign(!isShowModalShowCampaign)}>
                  <Eye size={16} />
                </Button.Ripple>
                <UncontrolledTooltip placement='top' target={`eye${row.id}`}>
                  Xem chi tiết
                </UncontrolledTooltip>
              </div>
              <div>
                <Button.Ripple id={`edit${row.id}`} className='btn-icon' color='flat-warning' onClick={isDisabled_2 ? () => {} : () => setIsShowModalEditCampaign(!isShowModalEditCampaign)} style={{
                  cursor: isDisabled_2 ? 'no-drop' : 'pointer'
                }}>
                  <Edit size={16} />
                </Button.Ripple>
                <UncontrolledTooltip placement='top' target={`edit${row.id}`}>
                 { isDisabled_2 ? 'Chỉ có thể chỉnh sửa trước khi chiến dịch diễn ra' : 'Chỉnh sửa'}
                </UncontrolledTooltip>
              </div>
              <div>
                <Button.Ripple id={`delete${row.id}`} className='btn-icon' color='flat-danger' onClick={isDisabled ? () => {} : () => handleDeleteCampaign()} style={{
                  cursor: isDisabled ? 'no-drop' : 'pointer'
                }}>
                  <Delete size={16}/>
                </Button.Ripple>
                <UncontrolledTooltip placement='top' target={`delete${row.id}`}>
                 { isDisabled ? 'Không thể xóa tại thời điểm chiến dịch đang diễn ra hoặc trạng thái đang bật' : 'Xóa'}
                </UncontrolledTooltip>
              </div>
              {
                false && (
                  <div>
                    <Button.Ripple id={`file${row.id}`} className='btn-icon' color='flat-success' onClick={() => handleExportRewardLinks()}>
                      <FileMinus size={16}/>
                    </Button.Ripple>
                    <UncontrolledTooltip placement='top' target={`file${row.id}`}>
                      Xuất mã dự thưởng
                    </UncontrolledTooltip>
                  </div>
                )
              }
              {
                true && (
                  <div style={{
                    marginTop: '7px',
                    marginLeft: '7px'
                  }}>
                    <div className='d-flex flex-column'>
                      <div id={`toggle${row.id}`} className='form-switch form-check-success'>
                        <Input checked={row.campaign_status_id === 2} type='switch' defaultChecked id={`icon-primary${row.id}`} name='icon-primary' onChange={(e) => handleUpdateCampaignStatus(e.target.checked, row.id)} />
                        <CustomLabel htmlFor={`icon-primary${row.id}`} />
                      </div>
                      <UncontrolledTooltip placement='top' target={`toggle${row.id}`}>
                        Cập nhật trạng thái
                      </UncontrolledTooltip>
                    </div>
                  </div>

                )
              }
          </div>
        </Fragment>
      )
    }
  }
  // ,{
  //   sortable: true,
  //   name: 'Salary',
  //   minWidth: '150px',
  //   selector: row => row.salary
  // }
]


export default ExpandableTable
