const ExportCustomers = () => {
  const store = useSelector(state => state.formShowCampaign)

  // ** Ref
  const tableRef = useRef()

  // ** States
  const [data, setData] = useState([])
  const [dataE, setDataE] = useState([])
  const [value, setValue] = useState('')
  const [modal, setModal] = useState(false)
  const [fileName, setFileName] = useState('')
  const [filteredData, setFilteredData] = useState([])
  const [fileFormat, setFileFormat] = useState('xlsx')
  const [countCustomer, setCountCustomer] = useState(0)
  const [isShow, setIsShow] = useState(false)
  const [dataImages, setDataImages] = useState([])

  useEffect(() => {
    const { customers } = store
    let stt = 0
    const arr = []
    const arr2 = [['STT', 'Mã tham gia', 'Họ và tên', 'Số điện thoại', 'Địa chỉ', 'Giải thưởng', 'Đại lý', 'Ảnh khách hàng']]
    customers.map(customer => {
      stt++
      arr.push(
        {
          stt,
          code: customer.RewardLinks.code,
          name: customer.RewardLinks.full_name,
          phone: `${customer.RewardLinks.phone_number.toString()}`,
          address: customer.RewardLinks.address,
          reward: customer.Rewards.name,
          nameAgency: customer.Agencies.name,
          resources: customer.resources
        }
      )
      let arrLinks = ''
      customer.resources.map(resource => {
        if (arrLinks !== '') arrLinks = `${arrLinks  }, ${jwtConfig.endPoint}${resource.file_path}`
        else arrLinks = `${jwtConfig.endPoint}${resource.file_path}`
      })
      arr2.push([
        stt,
        customer.RewardLinks.code,
        customer.RewardLinks.full_name,
        `${customer.RewardLinks.phone_number.toString()}`,
        customer.RewardLinks.address,
        customer.Rewards.name,
        customer.Agencies.name,
        arrLinks
      ])
    })

    setCountCustomer(stt)
    setData([...arr])
    setDataE(arr2)
  }, [store])

  const toggleModal = () => {
    setModal(!modal)
  }

  const handleFilter = e => {
    const dataArr = data
    let filteredData = []
    const value = e.target.value
    setValue(value)
    if (value.length) {
      filteredData = dataArr.filter(col => {
        const startsWithCondition =
          col.code.toLowerCase().startsWith(value.toLowerCase()) ||
          col.name.toLowerCase().startsWith(value.toLowerCase()) ||
          col.phone.toLowerCase().startsWith(value.toLowerCase()) ||
          col.address.toLowerCase().startsWith(value.toLowerCase()) ||
          col.reward.toLowerCase().startsWith(value.toLowerCase()) ||
          col.nameAgency.toString().toLowerCase().startsWith(value.toLowerCase())

        const includesCondition =
          col.code.toLowerCase().includes(value.toLowerCase()) ||
          col.name.toLowerCase().includes(value.toLowerCase()) ||
          col.phone.toLowerCase().includes(value.toLowerCase()) ||
          col.address.toLowerCase().includes(value.toLowerCase()) ||
          col.reward.toLowerCase().includes(value.toLowerCase()) ||
          col.nameAgency.toString().toLowerCase().includes(value.toLowerCase())

        if (startsWithCondition) return startsWithCondition
        else if (!startsWithCondition && includesCondition) return includesCondition
        else return null
      })
      setFilteredData(filteredData)
      setValue(value)
    }
  }

  const handleExport = () => {
    toggleModal()
    console.log("arr", data)
    const wb = XLSX.utils.book_new()
    const ws = XLSX.utils.aoa_to_sheet(dataE)

    XLSX.utils.book_append_sheet(wb, ws)
    XLSX.writeFileXLSX(wb, `${fileName}.${fileFormat}`)
    // const bookType = fileFormat
    // const wb = utils.table_to_book(tableRef.current, { sheet: 'Sheet JS' })
    // const wbout = write(wb, { bookType, bookSST: true, type: 'binary' })

    // const s2ab = s => {
    //   const buf = new ArrayBuffer(s.length)
    //   const view = new Uint8Array(buf)
    //   for (let i = 0; i < s.length; i++) view[i] = s.charCodeAt(i) & 0xff
    //   return buf
    // }
    // const file = fileName.length ? `${fileName}.${fileFormat}` : `excel-sheet.${fileFormat}`

    // return FileSaver.saveAs(new Blob([s2ab(wbout)], { type: 'application/octet-stream' }), file)
  }

  const array = value ? filteredData : data
  const handleModal = (dataImg) => {
    setIsShow(true)
    setDataImages(dataImg)
    console.log("iamges", data)
  }
  const renderTableData = array.map(col => {
    return (
      <tr key={col.id}>
        <td>{col.stt}</td>
        <td>{col.code}</td>
        <td>{col.name}</td>
        <td>{col.phone}</td>
        <td>{col.address}</td>
        <td>{col.reward}</td>
        <td>{col.nameAgency}</td>
        <td>
          <Button.Ripple id={`btn${col.id}`} outline color='primary' onClick={() => handleModal(col.resources)}>
            <Image size={14} />
            {/* <span className='align-middle ms-25'>Home</span> */}
          </Button.Ripple>
          <UncontrolledTooltip placement='top' target={`btn${col.id}`}>
            Xem hình ảnh
          </UncontrolledTooltip>
        </td>
      </tr>
    )
  })

  
  return (
    <Fragment>
      <>
        <Modal isOpen={isShow} toggle={() => setIsShow(!isShow)} className='modal-dialog-centered modal-md'>
          <ModalHeader className='bg-transparent' toggle={() => setIsShow(!isShow)}></ModalHeader>
          <ModalBody className='px-sm-5 mx-50 pb-5'>
            <div className='text-center mb-2'>
              <h1 className='mb-1 fw-bold'>Xem hình ảnh khách hàng</h1>
              <p>Bạn có thể xem hình ảnh khách hàng ở đây.</p>
            </div>
            <div className='mt-5'>
              <SwiperThreeD data={dataImages} />
            </div>
          </ModalBody>
        </Modal>
      </>
      <ExtensionsHeader
        title='XLSX'
        subTitle=''
        link='https://github.com/SheetJS/sheetjs'
      />
      <Row className='export-component'>
        <Col sm='12'>
          <Card>
            <CardBody className='pb-0'>
              <div className='d-flex justify-content-between flex-wrap flex-sm-row flex-column'>
                <Button color='primary' onClick={() => toggleModal()}>
                  Xuất
                </Button>
                Tổng cộng: {countCustomer}
                <div className='d-flex align-items-center justify-content-end mt-sm-0 mt-1'>
                  <Label for='search-input' className='me-1 text-nowrap'>
                    Tìm kiếm
                  </Label>
                  <Input id='search-input' bsSize='sm' type='text' value={value} onChange={e => handleFilter(e)} />
                </div>
              </div>
            </CardBody>
            <Table innerRef={tableRef} className='table-hover-animation mt-2' responsive>
              <thead>
                <tr>
                  <th>STT</th>
                  <th>Mã tham gia</th>
                  <th>Họ và tên</th>
                  <th>Số điện thoại</th>
                  <th>Địa chỉ</th>
                  <th>Giải thưởng</th>
                  <th>Đại lý</th>
                  <th>Hình ảnh</th>
                </tr>
              </thead>
              <tbody>{renderTableData}</tbody>
            </Table>
          </Card>
        </Col>
      </Row>
      <Modal
        isOpen={modal}
        toggle={() => toggleModal()}
        className='modal-dialog-centered'
        onClosed={() => setFileName('')}
      >
        <ModalHeader toggle={() => toggleModal()}>Xuất sang Excel</ModalHeader>
        <ModalBody>
          <div className='mb-2'>
            <Input
              type='text'
              value={fileName}
              onChange={e => setFileName(e.target.value)}
              placeholder='Nhập tên file'
            />
          </div>
          <div>
            <Input
              type='select'
              id='selectFileFormat'
              name='customSelect'
              value={fileFormat}
              onChange={e => setFileFormat(e.target.value)}
            >
              <option>xlsx</option>
              <option>csv</option>
              <option>txt</option>
            </Input>
          </div>
        </ModalBody>
        <ModalFooter>
          <Button color='primary' onClick={() => handleExport()}>
            Xuất
          </Button>
          <Button color='flat-danger' onClick={() => toggleModal()}>
            Đóng
          </Button>
        </ModalFooter>
      </Modal>
    </Fragment>
  )
}

export default ExportCustomers
