import { Fragment } from "react"
import { ArrowLeft, ArrowRight } from "react-feather"
import { useSelector } from "react-redux"
import { Button, Input } from "reactstrap"
import { Label } from "recharts"
import FileUploaderSingleCST from "../../FileUploader"
import SwiperThreeD from "../../SwiperCustom/3DEffect"

const CoverCampaign = ({stepper}) => {
  const store = useSelector(state => state.formShowCampaign)
  const {coverCampaign} = store

  return (
    <Fragment>
      <div className='content-header'>
        <h5 className='mb-0'>Ảnh chiến dịch</h5>
        <small className='text-muted'>...</small>
      </div>
      {/* <img alt="Ảnh chiến dịch" width="150" height="150" src="" />
      <Input type='file' id='inputFile' name='fileInput' /> */}
      <SwiperThreeD data={coverCampaign}/>
      <div className='d-flex justify-content-between mt-1'>
          <Button color='secondary' className='btn-prev' outline onClick={() => stepper.previous()}>
            <ArrowLeft size={14} className='align-middle me-sm-25 me-0'></ArrowLeft>
            <span className='align-middle d-sm-inline-block d-none'>Trước</span>
          </Button>
          <Button color='primary' className='btn-next' onClick={() => stepper.next()}>
            <span className='align-middle d-sm-inline-block d-none'>Tiếp theo</span>
            <ArrowRight size={14} className='align-middle ms-sm-25 ms-0'></ArrowRight>
          </Button>
      </div>
    </Fragment>
  )
}

export default CoverCampaign