import AvatarGroup from '@components/avatar-group'
import { MoreVertical, Edit, Trash } from 'react-feather'
import { Table, Badge, UncontrolledDropdown, DropdownMenu, DropdownItem, DropdownToggle } from 'reactstrap'
import { useSelector } from 'react-redux'
import { useState, useEffect } from 'react'
import jwtDefaultConfig from '@src/@core/auth/jwt/jwtDefaultConfig.js'
const TableShowReward = () => {
  const store = useSelector(state => state.formShowCampaign)
  const [rewards, setRewards] = useState(store.rewards)

  useEffect(() => {
    console.log("rewards", store.rewards)
    setRewards(store.rewards)
  }, [store])

  return (
    <Table responsive>
      <thead>
        <tr>
          <th>Tên giải thưởng</th>
          <th>Số lượng</th>
          <th>Mô tả</th>
          <th>Hình ảnh</th>
        </tr>
      </thead>
      <tbody>
        {
          rewards.map(reward => (
            <tr>
              <td>
                <span className='align-middle fw-bold'>{reward.name}</span>
              </td>
              <td>{reward.total_amount}</td>
              <td>
                {reward.description}
              </td>
              <td>
                <img style={{
                  objectFit: 'cover'
                }} src={`${jwtDefaultConfig.endPoint}${(reward.resources !== null && reward.resources.length > 0) ? reward.resources[0].file_path : ''}`} alt="Ảnh giải thưởng" width={60} height={60} />
              </td>
            </tr>
          ))
        }
      </tbody>
    </Table>
  )
}

export default TableShowReward