// ** React Imports
import { Fragment, useEffect } from 'react'
import { useDispatch, useSelector } from 'react-redux'

// ** Reactstrap Imports
import {
  Card,
  Row,
  Col,
  Modal,
  Input,
  Label,
  Button,
  CardBody,
  CardText,
  CardTitle,
  ModalBody,
  ModalHeader,
  FormFeedback
} from 'reactstrap'
import { getData, setFacebook, setHotline, setRewardDescription, setTreehut, setVHN, setYoutube, updateSocialLink } from './store'

// ** Third Party Components
// import { useDispatch } from 'react-redux'
// import FormAddAgent from '../'


const ModalSocialCampaign = (props) => {
  const {isShow, setIsShow} = props
  // const [isEditFunc, setIsEditFunc] = useState(false)
  const dispatch = useDispatch()
  const store = useSelector(state => state.formSocial)
  console.log(store)
  useEffect(() => {
    dispatch(
      getData()
    )
  }, [isShow])
  
  const handleVHN = (e) => {
    dispatch(
      setVHN(e.target.value)
    )
  }
  const handleTreehut = (e) => {
    dispatch(
      setTreehut(e.target.value)
    )
  }
  const handleFacebook = (e) => {
    dispatch(
      setFacebook(e.target.value)
    )
  }
  const handleYoutube = (e) => {
    dispatch(
      setYoutube(e.target.value)
    )
  }
  const handleHotline = (e) => {
    dispatch(
      setHotline(e.target.value)
    )
  }
  const handleRewardDescription = (e) => {
    dispatch(
      setRewardDescription(e.target.value)
    )
  }

  const handleUpdate = () => {
    dispatch(
      updateSocialLink(store)
    ).then(() => {
      setIsShow(false)
    })
  }

  return (
    <Fragment>
      <Modal isOpen={isShow} className='modal-dialog-centered modal-md'>
        <ModalHeader className='bg-transparent' toggle={() => setIsShow(!isShow)}></ModalHeader>
        <ModalBody className='px-sm-5 mx-50 pb-5'>
          <div className='text-center mb-2'>
            <h1 className='mb-1 fw-bold'>Thiết lập Social link</h1>
            <p>Bạn có thể điều chỉnh Social link tại đây.</p>
          </div>
          <Row className='gy-1 pt-75'>
            <Col sm='12' md='12' lg='12' className='mb-1'>
              <Label className='form-label'>
                VHN
              </Label>
              <Input type='text' value={store.vhn.link} onChange={(e) => handleVHN(e)}/>
              {/* {store.name === '' && <FormFeedback>Bạn chưa nhập tên chiến dịch</FormFeedback>} */}
            </Col>
            <Col sm='12' md='12' lg='12' className='mb-1'>
              <Label className='form-label'>
                Treehut
              </Label>
              <Input type='text' value={store.treehut.link} onChange={(e) => handleTreehut(e)}/>
              {/* {store.name === '' && <FormFeedback>Bạn chưa nhập tên chiến dịch</FormFeedback>} */}
            </Col>
            <Col sm='12' md='12' lg='12' className='mb-1'>
              <Label className='form-label'>
                Facebook
              </Label>
              <Input type='text' value={store.facebook.link} onChange={(e) => handleFacebook(e)}/>
              {/* {store.name === '' && <FormFeedback>Bạn chưa nhập tên chiến dịch</FormFeedback>} */}
            </Col>
            <Col sm='12' md='12' lg='12' className='mb-1'>
              <Label className='form-label'>
                Youtube
              </Label>
              <Input type='text' value={store.youtube.link} onChange={(e) => handleYoutube(e)}/>
              {/* {store.name === '' && <FormFeedback>Bạn chưa nhập tên chiến dịch</FormFeedback>} */}
            </Col>
            <Col sm='12' md='12' lg='12' className='mb-1'>
              <Label className='form-label'>
                Hotline
              </Label>
              <Input type='text' value={store.hotline.link} onChange={(e) => handleHotline(e)}/>
              {/* {store.name === '' && <FormFeedback>Bạn chưa nhập tên chiến dịch</FormFeedback>} */}
            </Col>
            <Col sm='12' md='12' lg='12' className='mb-1'>
              <Label className='form-label'>
                Hotline trang phần thưởng 
              </Label>
              <Input type='text' value={store.reward_description.link} onChange={(e) => handleRewardDescription(e)}/>
              {/* {store.name === '' && <FormFeedback>Bạn chưa nhập tên chiến dịch</FormFeedback>} */}
            </Col>
            <Col xs={12} className='text-center mt-2 pt-50'>
              <Button className='me-1' color={'success'} onClick={() => handleUpdate()}>
                Lưu lại
              </Button>
              <Button type='reset' color='secondary' outline onClick={() => setIsShow(false)}>
                Trở lại
              </Button>
            </Col>
          </Row>
        </ModalBody>
      </Modal>
    </Fragment>
  )
}

export default ModalSocialCampaign
