// ** Third Party Components
import Select from 'react-select'

// ** Utils
import { selectThemeColors } from '@utils'

// ** Reactstrap Imports
import { Card, CardHeader, CardTitle, CardBody, Row, Col, Label, FormFeedback } from 'reactstrap'
import { Fragment, useEffect, useState } from 'react'

// ** Styles
import '@styles/react/libs/react-select/_react-select.scss'
import { useSelector } from 'react-redux'
import { FastForward } from 'react-feather'


const SelectReactCST = ({onChange}) => {
  const store = useSelector(state => state.formAddCampaign)
  const [optionChoice, setOptionChoice] = useState(null)
  const [listAgenciesOptions, setlistAgenciesOptions] = useState([])

  useEffect(() => {
    const tmp = []
    console.log(store.listAgencies)
    const agencies = store.agencies
    const data = store.listAgencies.filter(item => {
      for (let i = 0; i < agencies.length; i++) {
        if (agencies[i].id === item.id) {
          return false
        }
      }
      return true
    })
    
    // console.log("change", data)
    if (optionChoice !== null) {
      tmp.push(optionChoice)
    }

    data.forEach(item => {
      tmp.push({
        value: item.id,
        label: `⫸ Tên: ${item.name} ⇿ Địa chỉ: ${item.address}`
      })
    })
    setlistAgenciesOptions(tmp)
  }, [store.agencies, store.listAgencies])

  const handleChange = (e) => {
    onChange(e.value)
    setOptionChoice(e)
  }
  return (
    <Fragment>
      <Label className='form-label'>Đại lý</Label>
      <Select
        theme={selectThemeColors}
        className={`react-select ${(optionChoice === null) ? 'is-invalid' : ''}`}
        classNamePrefix='select'
        options={listAgenciesOptions}
        placeholder="Chọn..."
        isClearable={false}
        onChange={(e) => handleChange(e)}
      />
      {(optionChoice === null) && <FormFeedback>Bạn chưa chọn đại lý</FormFeedback>}
    </Fragment>
  )
}
export default SelectReactCST
