// ** React Imports
import { useState, Fragment, useEffect, useRef } from 'react'

// ** Custom Components
import Repeater from '@components/repeater'

// ** Third Party Components
import { X, Plus } from 'react-feather'
import { SlideDown } from 'react-slidedown'

// ** Styles
import 'react-slidedown/lib/slidedown.css'

// ** Reactstrap Imports
import { Row, Col, Card, CardHeader, CardBody, CardText, Form, Label, Input, Button, FormFeedback } from 'reactstrap'
import SelectReactCST from '../SelectComponent'
import TextareaCST from '../TextAreaComponent'
import FileUploaderSingleCST from '../FileUploader'
import ColorPickerCST from '../ColorPickerCampaign'
import { useDispatch, useSelector } from 'react-redux'
import { setRewards } from '../FormEditCampainComponent/store'
import SwiperThreeD from '../SwiperCustom/3DEffect'

const FormRepeaterAwardsEditCST = ({setCheckValid, callBackShowValid}) => {
  // ** State
  const rewardSTT = useRef(0)
  rewardSTT.current = 0

  const store = useSelector(state => state.formEditCampaign)
  const [count, setCount] = useState(0)
  const [invalids, setInvalids] = useState([false])
  const [invalidsTotal, setInvalidsTotal] = useState([false])
  // console.log('Award', count)
  const [rowData, setRowData] = useState([])
  // {
    //   name: '',
    //   total_number: 0,
    //   description: '',
    //   status: true
    // }
  const dispatch = useDispatch()

  useEffect(() => {
    const rewardsArr = []
    store.rewardsBasic.map((item) => {
      rewardsArr.push({
        name: item.name,
        total_number: item.total_amount,
        description: item.description,
        status: true,
        fileCurrent: [
          {
            id: (item.resources !== null && item.resources.length > 0) ? item.resources[0].id : "",
            file_path: (item.resources !== null && item.resources.length > 0) ? item.resources[0].file_path : ""
          }
        ]
      })
    })
    setRowData([...rewardsArr])
    setCount(rewardsArr.length)
  }, [store.rewardsBasic])

  const handleShowInValid = () => {
    const tmp = [...invalids]
    const tmp2 = [...invalidsTotal]
    rowData.map((item, index) => {
      if (item.status) {
        if (item.name === '') {
          tmp[index] = true
        }
        if (item.total_number === 0) {
          tmp2[index] = true
        }
      }
    })
    setInvalids([...tmp])
    setInvalidsTotal([...tmp2])
  }
  
  useEffect(() => {
    const rowDataFilter = rowData.filter(item => item.status === true && (item.name ===  '' || item.total_number === ''))
    setCheckValid(rowDataFilter.length > 0)
    callBackShowValid(handleShowInValid())
    dispatch(
      setRewards({
        rewards: rowData.filter(item => item.status !== false && item.name !== '' && item.total_number !== '')
      })
    )
  }, [rowData])


  const increaseCount = () => {
    setCount(count + 1)
    setRowData([
      ...rowData,
      {
        name: '',
        total_number: '',
        description: '',
        status: true
      }
    ])
  }

  const deleteForm = (e, i) => {
    e.preventDefault()
    const slideDownWrapper = e.target.closest('.react-slidedown'),
    form = e.target.closest('form')
    if (slideDownWrapper) {
      slideDownWrapper.remove()
    } else {
      form.remove()
    }

    const tmp = []
    Object.assign(tmp, [...rowData])
    tmp[i] = {
      ...tmp[i],
      status: false
    }
    setRowData([...tmp])
  }
  
  const handleNameAward = (value, i) => {
    console.log('name', i)
    const tmp = []
    Object.assign(tmp, [...rowData])
    tmp[i] = {
      ...tmp[i],
      name: value
    }
    setRowData([...tmp])
  }

  const handleNumberAward = (value, i) => {
    const tmp = []
    Object.assign(tmp, [...rowData])
    tmp[i] = {
      ...tmp[i],
      total_number: value
    }
    setRowData([...tmp])
  }

  const handleDescribeAward = (value, i) => {
    const tmp = []
    Object.assign(tmp, [...rowData])
    tmp[i] = {
      ...tmp[i],
      description: value
    }
    setRowData([...tmp])
  }

  const handleFile = (value, i) => {
    const tmp = []
    Object.assign(tmp, [...rowData])
    tmp[i] = {
      ...tmp[i],
      file: value
    }
    setRowData([...tmp])
  }

  useEffect(() => {
    setInvalids(prev => [...prev, false])
    setInvalidsTotal(prev => [...prev, false])
  }, [count])
  return (
    <Fragment>
       <Repeater count={count}>
          {i => {
            const Tag = i === 0 ? 'div' : SlideDown
            if (rowData[i].status) rewardSTT.current++
            return (
              <Tag key={i}>
                <Form>
                  <b>{rewardSTT.current}</b>
                  <Row className='justify-content-between align-items-center'>
                    <Col lg={8} md={12} sm={12} className='mb-md-0 mb-1'>
                      {/* <SelectReactCST /> */}
                      <Label className='form-label'>
                        Tên giải thưởng
                      </Label>
                      <Input value={rowData[i].name} type='text' onChange={(e) => { 
                        e.target.className = `form-control ${(e.target.value === '' || e.target.value === null) ? 'is-invalid' : ''}`
                        const tmp = [...invalids]
                        tmp[i] = (e.target.value === '' || e.target.value === null)
                        setInvalids([...tmp])
                        handleNameAward(e.target.value, i)
                      }} placeholder='Nhập tên giải thưởng' />
                      {(invalids[i]) && <FormFeedback>Bạn chưa nhập tên giải thưởng</FormFeedback>}
                    </Col>
                    <Col lg={4} md={12} sm={12} className='mb-md-0 mb-1'>
                      <Label className='form-label'>
                        Số lượng
                      </Label>  
                      <Input value={rowData[i].total_number} type='number' placeholder='' defaultValue={0} onChange={(e) => {
                        e.target.className = `form-control ${(e.target.value === '' || e.target.value === null || e.target.value < 0) ? 'is-invalid' : ''}`
                        const tmp = [...invalidsTotal]
                        tmp[i] = (e.target.value === '' || e.target.value === null || e.target.value < 0)
                        setInvalidsTotal([...tmp])
                        handleNumberAward(e.target.value, i)
                      }} />
                      {(invalidsTotal[i]) && <FormFeedback>Số lượng giải thưởng phải lớn hơn 0</FormFeedback>}
                    </Col>
                    {/* <Col md={2} className='mb-md-0 mb-1'>
                      <Label className='form-label' for={`animation-quantity-${i}`}>
                        Tỷ lệ trúng
                      </Label>
                      <Input type='number' id={`animation-quantity-${i}`} placeholder='1' />
                    </Col> */}
                    <Col lg={12} md={12} sm={12} className='mb-md-0 mb-1'>
                      <TextareaCST defaultV ={rowData[i].description} width="100px" setValue={(value) => handleDescribeAward(value, i)}/>
                      {/* <Input type='text' id={`animation-quantity-${i}`} placeholder='' /> */}
                    </Col>
                    <Col lg={12} md={12} sm={12} className='mb-md-0 mb-1 mt-2' >
                      {
                        (rowData[i].fileCurrent !== undefined && rowData[i].fileCurrent !== null) && (
                          <div className="mb-4">
                            <div>
                              <b>Ảnh hiện tại 🡖</b>
                            </div>
                            <div className="mt-3">
                              <SwiperThreeD data={rowData[i].fileCurrent}/>
                            </div>
                          </div>
                        )
                      }
                      <Label className='form-label' >
                        Hình ảnh
                      </Label>
                      <div>
                        <FileUploaderSingleCST tranferFiles={(value) => handleFile(value, i)} isOnlyOneImage={true} />
                      </div>
                    </Col>
                    {/* <Col md={4} className='mb-md-0 mb-1' >
                      <Label className='form-label'>
                        Màu sắc
                      </Label>
                      <ColorPickerCST />
                    </Col> */}
                    <Col md={6}>
                      <Button color='danger' className='text-nowrap px-1 mt-2' onClick={(e) => deleteForm(e, i)} outline>
                        <X size={14} className='me-50' />
                        <span>Xóa</span>
                      </Button>
                    </Col>
                    <Col sm={12}>
                      <hr />
                    </Col>
                  </Row>
                </Form>
              </Tag>
            )
          }}
        </Repeater>
        <Button className='btn-icon' color='primary' onClick={increaseCount}>
          <Plus size={14} />
          <span className='align-middle ms-25'>Thêm giải thưởng</span>
        </Button>
    </Fragment>
  )
}

export default FormRepeaterAwardsEditCST
