// ** React Imports
import { Fragment, useState, useEffect } from 'react'

// ** Icons Imports
import { ArrowLeft, ArrowRight } from 'react-feather'
import { useSelector } from 'react-redux'

// ** Reactstrap Imports
import { Label, Row, Col, Input, Form, Button } from 'reactstrap'
import FileUploaderSingleCST from '../../FileUploader/index.js'
import PickerDate from '../../PickerDate/index.js'
import TextareaCST from '../../TextAreaComponent/index.js'
const CampaignInfo = ({ stepper }) => {
  
  const store = useSelector(state => state.formShowCampaign)
  const {campaignInfo} = store
  const [dateStart, setDateStart] = useState()
  const [dateEnd, setDateEnd] = useState()

  useEffect(() => {
    const dStart = new Date(campaignInfo.startDate)
    const eStart = new Date(campaignInfo.endDate)
    setDateStart(`${(`0${dStart.getDate()}`).slice(-2)}-${(`0${dStart.getMonth() + 1}`).slice(-2)}-${dStart.getFullYear()} ${`0${dStart.getHours()}`.slice(-2)}:${`0${dStart.getMinutes()}`.slice(-2)}`)
    setDateEnd(`${(`0${eStart.getDate()}`).slice(-2)}-${(`0${eStart.getMonth() + 1}`).slice(-2)}-${eStart.getFullYear()} ${`0${eStart.getHours()}`.slice(-2)}:${`0${eStart.getMinutes()}`.slice(-2)}`)
  }, [store])

  return (
    <Fragment>
      <div className='content-header'>
        <h5 className='mb-0'>THÔNG TIN CHUNG</h5>
        <small className='text-muted'>...</small>
      </div>
      <Form onSubmit={e => e.preventDefault()}>
        <Row>
          <Col md='6' className='mb-1'>
            <Label className='form-label'>
              Tên chiến dịch
            </Label>
            <Input value={campaignInfo.name} isDisable type='text'/>
          </Col>
          <Col md='6' className='mb-1'>
            <Label className='form-label'>
              Ngày bắt đầu
            </Label>
            <Input isDisable type='text' value={dateStart} />

          </Col>
          <Col md='6' className='mb-1'>
            <Label className='form-label'>
              Ngày kết thúc
            </Label>
            <Input isDisable type='text' value={dateEnd} />
          </Col>
          <Col md='6' className='mb-1'>
             <div className='form-floating mt-2'>
              <Input
                type='textarea'
                name='text'
                id='floating-textarea'
                placeholder='Floating Label'
                style={{ minHeight: '100px' }}
                value={campaignInfo.description}
              />
              <Label className='form-label' for='floating-textarea'>
                Mô tả
              </Label>
            </div>
          </Col>
        </Row>
        <div className='d-flex justify-content-between'>
          <Button color='secondary' className='btn-prev' outline disabled>
            <ArrowLeft size={14} className='align-middle me-sm-25 me-0'></ArrowLeft>
            <span className='align-middle d-sm-inline-block d-none'>Trước</span>
          </Button>
          <Button color='primary' className='btn-next' onClick={() => stepper.next()}>
            <span className='align-middle d-sm-inline-block d-none'>Tiếp theo</span>
            <ArrowRight size={14} className='align-middle ms-sm-25 ms-0'></ArrowRight>
          </Button>
        </div>
      </Form>
    </Fragment>
  )
}

export default CampaignInfo
