// ** React Imports
import { Fragment, useEffect, useMemo } from 'react'

// ** Reactstrap Imports
import {
  Card,
  Row,
  Col,
  Modal,
  Input,
  Label,
  Button,
  CardBody,
  CardText,
  CardTitle,
  ModalBody,
  ModalHeader,
  FormFeedback
} from 'reactstrap'

// ** Third Party Components
import Select from 'react-select'
import { User, Check, X } from 'react-feather'
import FormAddCampain from '../FormAddCampainComponent'
import { getAgencies, getData } from '../FormEditCampainComponent/store'
import { closeSwal, handleLoading } from '../../sweetalert'
import { useDispatch } from 'react-redux'
import FormEditCampain from '../FormEditCampainComponent'
// import FormAddAgent from '../'


const ModalEditCampain = (props) => {
  const {isShow, setIsShow, data} = props
  // const [isEditFunc, setIsEditFunc] = useState(false)
  const dispatch = useDispatch()

  useEffect(() => {
    dispatch(
      getAgencies()
    )
  })

  useMemo(() => {
    console.log("isShow", isShow)
    console.log("data", data)
    if (isShow) {
      handleLoading("Vui lòng chờ hệ thống...")
      dispatch(
        getData(data)
      )
      .then(() => {
        closeSwal()
      })
    }
  }, [isShow])

  return (
    <Fragment>
      <Modal isOpen={isShow} className='modal-dialog-centered modal-fullscreen'>
        <ModalHeader className='bg-transparent' toggle={() => setIsShow(!isShow)}></ModalHeader>
        <ModalBody className='px-sm-5 mx-50 pb-5'>
          <div className='text-center mb-2'>
            <h1 className='mb-1 fw-bold'>Chỉnh sửa chiến dịch</h1>
            <p>Bạn có thể sửa một chiến dịch mới ở đây.</p>
          </div>
          <Row className='gy-1 pt-75'>
            <Col sm="12">
              <div>
                <FormEditCampain showModalParent={(value) => setIsShow(value)} />
              </div>
            </Col>
            <Col xs={12} className='text-center mt-2 pt-50'>
              {/* <Button className='me-1' color={(!isEditFunc) ? 'primary' : 'success'} onClick={() => setIsEditFunc(!isEditFunc)}>
                {(!isEditFunc) ? 'Chỉnh sửa' : 'Lưu lại' }
              </Button> */}
              <Button type='reset' color='secondary' outline onClick={() => setIsShow(false)}>
                Trở lại
              </Button>
            </Col>
          </Row>
        </ModalBody>
      </Modal>
    </Fragment>
  )
}

export default ModalEditCampain
