// ** Third Party Components
import { Swiper, SwiperSlide } from 'swiper/react/swiper-react'
// ** Hooks
import { useRTL } from '@hooks/useRTL'
import jwtConfig from '@src/@core/auth/jwt/jwtDefaultConfig.js'
// ** Styles
import '@styles/react/libs/swiper/swiper.scss'
import SwiperCore, {
  Grid,
  Lazy,
  Virtual,
  Autoplay,
  Navigation,
  Pagination,
  EffectFade,
  EffectCube,
  EffectCoverflow
} from 'swiper'
// ** Init Swiper Functions
SwiperCore.use([Navigation, Grid, Pagination, EffectFade, EffectCube, EffectCoverflow, Autoplay, Lazy, Virtual])
// ** Reactstrap Imports
import { Card, CardHeader, CardTitle, CardBody } from 'reactstrap'

// ** Images
// import img1 from '@src/assets/images/banner/banner-21.jpg'
// import img2 from '@src/assets/images/banner/banner-22.jpg'
// import img3 from '@src/assets/images/banner/banner-23.jpg'
// import img4 from '@src/assets/images/banner/banner-24.jpg'

const params = {
  effect: 'cube',
  pagination: {
    clickable: true
  },
  cubeEffect: {
    shadow: true,
    shadowOffset: 20,
    shadowScale: 0.94,
    slideShadows: true
  }
}

const SwiperThreeD = ({data}) => {
   // ** Hooks
  const [isRtl] = useRTL()
  return (
    // <Card>
    //   <CardHeader>
    //     <CardTitle tag='h4'>3D Cube Effect</CardTitle>
    //   </CardHeader>
    //   <CardBody>
        <Swiper {...params} dir={isRtl ? 'rtl' : 'ltr'}>
          {
            (data !== null && data !== undefined && data.length > 0) && data.map(item => (
              <SwiperSlide>
                <img src={`${jwtConfig.endPoint}${item.file_path}`} alt='swiper 1' width={300} height={300} style={{
                  objectFit: 'contain'
                }}/>
              </SwiperSlide>
            ))
          }
        </Swiper>
    //   </CardBody>
    // </Card>
  )
}

export default SwiperThreeD
