// ** React Imports
import { useState, Fragment, useEffect, useRef } from 'react'

// ** Custom Components
import Repeater from '@components/repeater'

// ** Third Party Components
import { X, Plus } from 'react-feather'
import { SlideDown } from 'react-slidedown'

// ** Styles
import 'react-slidedown/lib/slidedown.css'

// ** Reactstrap Imports
import { Row, Col, Card, CardHeader, CardBody, CardText, Form, Label, Input, Button } from 'reactstrap'
import SelectReactCST from '../SelectComponent'
import { useDispatch } from 'react-redux'
import { setAgencies } from '../FormAddCampainComponent/store'

// eslint-disable-next-line no-var
const FormRepeaterAgenciesCST = (props) => {
  const sttRow = useRef(0)
  sttRow.current = 0
  // ** State
  const {setLengthData} = props
  const [rowData, setRowData] = useState(
    [
      {
        id: -1,
        total_number: 0
      }
    ]
  )
  const [count, setCount] = useState(1)
  const dispatch = useDispatch()

  useEffect(() => {
    setLengthData(rowData.filter(item => (item.id === -1 || (item.id !== -2 && (item.total_number <= 0 || item.total_number === '')))).length)
    dispatch(
      setAgencies(
        {
          agencies: rowData.filter(item => (item.id !== -1 && item.id !== -2))
        }
      )
    )
  }, [rowData])

  const increaseCount = () => {
    setCount(count + 1)
    setRowData([
      ...rowData,
      {
        id: -1,
        total_number: 0
      }
    ])
  }

  const deleteForm = (e, i) => {
    e.preventDefault()
    const slideDownWrapper = e.target.closest('.react-slidedown'),
      form = e.target.closest('form')
    if (slideDownWrapper) {
      slideDownWrapper.remove()
    } else {
      form.remove()
    }

    const tmp = []
    Object.assign(tmp, [...rowData])
    tmp[i] = {
      ...tmp[i],
      id: -2
    }
    setRowData([...tmp])
  }

  const handleOnChangeSelect = (value, i) => {
    const tmp = []
    Object.assign(tmp, [...rowData])
    tmp[i] = {
      ...tmp[i],
      id: value
    }
    setRowData([...tmp])
  }

  const handleOnChangeInput = (value, i) => {
    console.log(value, i)
    const tmp = []
    Object.assign(tmp, [...rowData])
    tmp[i] = {
      ...tmp[i],
      total_number: value
    }
    setRowData([...tmp])
  }

  return (
    <Fragment>
       <Repeater count={count}>
          {i => {
            if (rowData[i].id !== -2) sttRow.current++
            const Tag = i === 0 ? 'div' : SlideDown
            return (
              <Tag key={i}>
                <Form>
                  <b>{sttRow.current}</b>
                  <Row className='justify-content-between align-items-center'>
                    <Col md={8} className='mb-md-0 mb-1'>
                      {/* <Label className='form-label'>Chọn chủ đại lý</Label> */}
                      <SelectReactCST index={i}  onChange={(value) => handleOnChangeSelect(value, i)}/>
                    </Col>
                    <Col md={4} className='mb-md-0 mb-1'>
                      <Label className='form-label'>
                        Số lượng giải phân bổ
                      </Label>
                      <Input type='number' onChange={(e) => handleOnChangeInput(e.target.value, i)}/>
                    </Col>
                    <Col md={4}>
                      <Button color='danger' className='text-nowrap px-1 mt-2' onClick={(e) => deleteForm(e, i)} outline>
                        <X size={14} className='me-50' />
                        <span>Xóa</span>
                      </Button>
                    </Col>
                    <Col sm={12}>
                      <hr />
                    </Col>
                  </Row>
                </Form>
              </Tag>
            )
          }}
        </Repeater>
        <Button className='btn-icon' color='primary' onClick={increaseCount}>
          <Plus size={14} />
          <span className='align-middle ms-25'>Thêm đại lý</span>
        </Button>
    </Fragment>
  )
}

export default FormRepeaterAgenciesCST
