// ** React Imports
import { Fragment, useState, useEffect, memo, useRef } from 'react'

// ** Table Columns
import { serverSideColumns } from './data'

// ** Store & Actions
import { deleteCampaigns, getData, reloadTable } from './store'
import { useSelector, useDispatch } from 'react-redux'

// ** Third Party Components
import ReactPaginate from 'react-paginate'
import { ChevronDown, Delete, Home, Plus, Settings } from 'react-feather'
import DataTable from 'react-data-table-component'
// import ModalAddAgent from '../ModalAddAgentComponent'
// ** Reactstrap Imports
import { Card, CardHeader, CardTitle, Input, Label, Row, Col, Button, Spinner } from 'reactstrap'
import ModaAddCampain from '../ModalAddCampainComponent'
import { useNavigate } from 'react-router-dom'
import ModalSocialCampaign from '../ModalSocialLinkComponent'
import { handleQuestion } from '../../sweetalert'
// import { deleteCampaigns } from '../FormAddCampainComponent/store'
// import { exportRewardLinks } from '../../../../utility/Utils'

const DataTableServerSide = () => {
  const [arrSelectedRows, setArrSelectedRows] = useState([])
  const [toggleClearSeRow, setToggleClearSeRow] = useState(false)
  // ** Store Vars
  const dispatch = useDispatch()
  const store = useSelector(state => state.datatablesCampaign)
  const navigate = useNavigate()
  // ** States
  const [currentPage, setCurrentPage] = useState(1)
  const [rowsPerPage, setRowsPerPage] = useState(7)
  const [searchValue, setSearchValue] = useState('')
  const [isShowLoading, setIsShowLoading] = useState(false)

  // ** Get data on mount
  useEffect(() => {
    setIsShowLoading(true)
    dispatch(
      getData({
        page: currentPage,
        perPage: rowsPerPage,
        q: searchValue
      })
    ).then((response) => {
      setIsShowLoading(false)
      const {error} = response.payload
      if (error !== null) {
        if (error.response.status === 401) {
          navigate('/login')
        }
      }
    })
  }, [dispatch])

  // ** Function to handle filter
  const handleAfterFilter = (e) => {
    dispatch(
      getData({
        page: currentPage,
        perPage: rowsPerPage,
        q: e.target.value
      })
    ).then(() => {
      setIsShowLoading(false)
    })
  }
  const timeRef = useRef()
  const handleFilter = e => {
    setIsShowLoading(true)
    setSearchValue(e.target.value)
    clearTimeout(timeRef.current)
    timeRef.current = setTimeout(() => {
      handleAfterFilter(e)
    }, 200)

  }

  // ** Function to handle Pagination and get data
  const handlePagination = page => {
    setIsShowLoading(true)
    dispatch(
      getData({
        page: page.selected + 1,
        perPage: rowsPerPage,
        q: searchValue
      })
    ).then(() => {
      setIsShowLoading(false)
    })
    setCurrentPage(page.selected + 1)
  }

  // ** Function to handle per page
  const handlePerPage = e => {
    setIsShowLoading(true)
    dispatch(
      getData({
        page: currentPage,
        perPage: parseInt(e.target.value),
        q: searchValue
      })
    ).then(() => {
      setIsShowLoading(false)
    })
    setRowsPerPage(parseInt(e.target.value))
  }

  // ** Custom Pagination
  const CustomPagination = () => {
    const count = store.total

    return (
      <ReactPaginate
        previousLabel={''}
        nextLabel={''}
        breakLabel='...'
        pageCount={Math.ceil(count) || 1}
        marginPagesDisplayed={2}
        pageRangeDisplayed={2}
        activeClassName='active'
        forcePage={currentPage !== 0 ? currentPage - 1 : 0}
        onPageChange={page => handlePagination(page)}
        pageClassName='page-item'
        breakClassName='page-item'
        nextLinkClassName='page-link'
        pageLinkClassName='page-link'
        breakLinkClassName='page-link'
        previousLinkClassName='page-link'
        nextClassName='page-item next-item'
        previousClassName='page-item prev-item'
        containerClassName={
          'pagination react-paginate separated-pagination pagination-sm justify-content-end pe-1 mt-1'
        }
      />
    )
  }

  // const handlerExportExcel = async () => {
  //   setOnExportExcel(true)

  //   await exportRewardLinks({
  //     used: false
  //   })

  //   setOnExportExcel(false)
  // }
  // ** Table data to render
  const dataToRender = () => {
    const filters = {
      q: searchValue
    }

    const isFiltered = Object.keys(filters).some(function (k) {
      return filters[k].length > 0
    })

    if (store.data.length > 0) {
      return store.data
    } else if (store.data.length === 0 && isFiltered) {
      return []
    } else {
      return store.allData.slice(0, rowsPerPage)
    }
  }

  const handleSelectRow = (state) => {
    console.log(state)
    setArrSelectedRows(state.selectedRows)
    
  }

  const handleDeleteRows = () => {
    handleQuestion("Bạn muốn tiếp tục?", "Việc xóa liên tiếp các chiến dịch sẽ không thể hoàn tác lại", (isConfirmed) => {
      if (isConfirmed) {
        dispatch(
          deleteCampaigns({
            data: arrSelectedRows,
            reloadTable: async () => {
              dispatch(
                reloadTable({
                  getData: async (params) => await dispatch(getData(params))
                })
              )
            }
          })
        ).then(() => {
          setArrSelectedRows([])
          setToggleClearSeRow(!toggleClearSeRow)
        })
      }
    })
  }
  // state
  const [isShowAddCampain, setIsShowAddCampain] = useState(false)
  const [isShowSocialCampaign, setShowSocialCampaign] = useState(false)

  const rowDisableSelected = row => {
    let date =  new Date()
    date = new Date(`${date.getFullYear()}-${`0${date.getMonth() + 1}`.slice(-2)}-${`0${date.getDate()}`.slice(-2)} ${`0${date.getHours()}`.slice(-2)}:${`0${date.getMinutes()}`.slice(-2)}`)
    let dateStart = new Date(row.start_date)
    dateStart = new Date(`${dateStart.getFullYear()}-${`0${dateStart.getMonth() + 1}`.slice(-2)}-${`0${dateStart.getDate()}`.slice(-2)} ${`0${dateStart.getHours()}`.slice(-2)}:${`0${dateStart.getMinutes()}`.slice(-2)}`)
    let endStart = new Date(row.end_date)
    endStart = new Date(`${endStart.getFullYear()}-${`0${endStart.getMonth() + 1}`.slice(-2)}-${`0${endStart.getDate()}`.slice(-2)} ${`0${endStart.getHours()}`.slice(-2)}:${`0${endStart.getMinutes()}`.slice(-2)}`)
    const isDisabled = (row.campaign_status_id === 2 || (dateStart.getTime() <= date.getTime() && date.getTime() <= endStart.getTime()))
    return isDisabled
  }
  return (
    <Fragment>
      <ModalSocialCampaign isShow={isShowSocialCampaign} setIsShow={setShowSocialCampaign} />
      <ModaAddCampain isShow={isShowAddCampain} setIsShow={setIsShowAddCampain} />
      {/* <ModalAddAgent isShow={isShowAddAgent} setIsShow={setIsShowAddAgent}/> */}
      <Card>
        <CardHeader className='border-bottom'>
          <CardTitle tag='h4'>Danh sách chiến dịch</CardTitle>
        </CardHeader>
        <Row>
          <Col md={12} lg={12} sm={12}>
            <Button.Ripple color='primary' className='m-1' onClick={() => setIsShowAddCampain(!isShowAddCampain)}>
              <Plus size={14} />
              <span className='align-middle ms-25'>Thêm chiến dịch</span>
            </Button.Ripple>
            
            {/* <Button hidden disabled={onExportExcel} color="primary" onClick={handlerExportExcel}>
              {onExportExcel && <Spinner style={{  marginRight: '10px' }} size="sm"/>} 
              Xuất Excel 
            </Button> */}
            <Button.Ripple color='info' className='m-1' onClick={() => setShowSocialCampaign(!isShowSocialCampaign)}>
              <Settings size={14} />
              <span className='align-middle ms-25'>Social Link</span>
            </Button.Ripple>
          </Col>
        </Row>
        <Row className='mx-0 mt-1 mb-50'>
          <Col sm='6'>
            <div className='d-flex align-items-center'>
              <Label for='sort-select'>Hiển thị</Label>
              <Input
                className='dataTable-select'
                type='select'
                id='sort-select'
                value={rowsPerPage}
                onChange={e => handlePerPage(e)}
              >
                <option value={7}>7</option>
                <option value={10}>10</option>
                <option value={25}>25</option>
                <option value={50}>50</option>
                <option value={75}>75</option>
                <option value={100}>100</option>
              </Input>
              <Label for='sort-select'>hàng</Label>
            </div>
          </Col>
          <Col className='d-flex align-items-center justify-content-sm-end mt-sm-0 mt-1' sm='6'>
            <div className='me-1'>
                {
                  (isShowLoading) &&
                  <Spinner color='primary' />
                }
            </div>
            <Label className='me-1' for='search-input'>
              Tìm kiếm
            </Label>
            <Input
              className='dataTable-filter'
              type='text'
              bsSize='sm'
              id='search-input'
              value={searchValue}
              onChange={handleFilter}
            />
          </Col>
        </Row>
        {
          arrSelectedRows.length > 0 && (
            <Row>
              <Col sm='12'>
                <Button.Ripple outline color='danger' className='m-1' onClick={() => handleDeleteRows()}>
                  <Delete size={14}/>
                  <span className='ms-1 align-middle ms-25'>Xóa các hàng</span>
                </Button.Ripple>
              </Col>
            </Row>
          )
        }
        <div className='react-dataTable'>
          <DataTable
            selectableRows
            selectableRowsHighlight
            onSelectedRowsChange={handleSelectRow}
            selectableRowDisabled={rowDisableSelected}
            clearSelectedRows={toggleClearSeRow}
            noHeader
            pagination
            paginationServer
            className='react-dataTable'
            columns={serverSideColumns}
            sortIcon={<ChevronDown size={10} />}
            paginationComponent={CustomPagination}
            data={dataToRender()}
          />
        </div>
      </Card>
    </Fragment>
  )
}

export default memo(DataTableServerSide)
