import { Fragment } from "react"
import { ArrowLeft, ArrowRight } from "react-feather"
import toast from "react-hot-toast"
import { useDispatch, useSelector } from "react-redux"
import { Alert, Button, Input } from "reactstrap"
import { Label } from "recharts"
import FileUploaderSingleCST from "../../FileUploader"
import { setCoverRotation } from "../store"
import Resizer from "react-image-file-resizer"

const CoverRotation = ({stepper}) => {
  const dispatch = useDispatch()
  const store = useSelector(state => state.formAddCampaign)
  
  const resizeFile = (file, width, height) => new Promise(resolve => {
    Resizer.imageFileResizer(file, width, height, 'PNG', 100, 0,
      uri => {
        resolve(uri)
      }, 'base64')
  })

  const dataURLtoFile = (dataurl, filename) => {
    const arr = dataurl.split(',')
    const mime = arr[0].match(/:(.*?);/)[1]
    const bstr = atob(arr[1])
    let n = bstr.length 
    const u8arr = new Uint8Array(n)

    while (n--) {
        u8arr[n] = bstr.charCodeAt(n)
    }
    
    return new File([u8arr], filename, {type:mime})
}
  const handleSetCoverRotation = async (value) => {
    if (value.length > 0) {
      const image_1 = await resizeFile(value[0], 674, 674)
      const image_2 = await resizeFile(value[0], 808, 808)
      const image_3 = await resizeFile(value[0], 410, 410)
      const c_image_1 =  dataURLtoFile(image_1, 'img1.png')
      const c_image_2 =  dataURLtoFile(image_2, 'img2.png')
      const c_image_3 =  dataURLtoFile(image_3, 'img3.png')
      dispatch(
        setCoverRotation(
          {
            coverRotations: [
              c_image_1,
              c_image_2,
              c_image_3
            ]
          }
        )
      )
    } else {
      dispatch(
        setCoverRotation(
          {
            coverRotations: []
          }
        )
      )
    }
  }
  const handleNext = () => {
    if (store.coverRotation === null || store.coverRotation === undefined || store.coverRotation === "" || store.coverRotation.length === 0) {
      toast.error("Bạn chưa chọn ảnh vòng quay")
      return
    }
    const reader = new FileReader()
    reader.onload = (e) => {
      const image = new Image()
      image.src = (e.target.result)
      image.onload = () => {
        if (image.width - 808 < 0) {
          toast.error("Chiều dài và chiều cao của ảnh phải lớn hơn hoặc bằng 808px")
          return
        }
        if (Math.round(image.width / image.height) !== 1) {
          toast.error("Ảnh phải là hình vuông (tỷ lệ hai kích thước 0.5 < x < 1.5)")
          return
        }
        stepper.next()
      }
    }
    reader.readAsDataURL(store.coverRotation[1])
  }
  return (
    <Fragment>
      
      <div className='content-header'>
        <h5 className='mb-0'>Ảnh vòng quay</h5>
        <small className='text-muted'>...</small>
      </div>
      <Alert color='primary'>
        <div className='alert-body'>
          <span className='fw-bold'>Chú ý: </span>
          <span>
            Hãy thêm 1 ảnh với kích thước là 808px
          </span>
        </div>
      </Alert>
      <FileUploaderSingleCST tag={'png'} accept={['.png']} multiple={false} tranferFiles={(value) => handleSetCoverRotation(value)} isOnlyOneImage={true}/>
      <div className='d-flex justify-content-between mt-1'>
          <Button color='secondary' className='btn-prev' outline onClick={() => stepper.previous()}>
            <ArrowLeft size={14} className='align-middle me-sm-25 me-0'></ArrowLeft>
            <span className='align- iddle d-sm-inline-block d-none'>Trước</span>
          </Button>
          <Button color='primary' className='btn-next' onClick={() => handleNext()}>
            <span className='align-middle d-sm-inline-block d-none'>Tiếp theo</span>
            <ArrowRight size={14} className='align-middle ms-sm-25 ms-0'></ArrowRight>
          </Button>
      </div>
    </Fragment>
  )
}

export default CoverRotation