import useJwt from '@src/auth/jwt/useJwt'
// ** React Imports
import { useState, Fragment, useMemo, useRef } from 'react'

// ** Custom Components
import Repeater from '@components/repeater'

// ** Third Party Components
import { X, Plus } from 'react-feather'
import { SlideDown } from 'react-slidedown'

// ** Styles
import 'react-slidedown/lib/slidedown.css'

// ** Reactstrap Imports
import { Row, Col, Card, CardHeader, CardBody, CardText, Form, Label, Input, Button } from 'reactstrap'
import { useDispatch, useSelector } from 'react-redux'
import { setAgencies } from '../FormEditCampainComponent/store'
import SelectEditReactCST from '../SelectEditComponent'

// eslint-disable-next-line no-var
const FormRepeaterAgenciesEditCST = (props) => {
  // ** State
  const store = useSelector(state => state.formEditCampaign)
  const {setLengthData} = props
  const [rowData, setRowData] = useState([])
  const [count, setCount] = useState(0)
  const indexSTT = useRef(0)
  useMemo(async () => {
    const agencies = []
    const getDetailAgencies = store.agenciesBasic.map(async (agency) => {
      const agency_campaign = await useJwt.getAgencyCampaign({
        id: agency.agency_campaign_id
      })
      agencies.push({
        id: agency.id,
        total_number: agency_campaign.data.reward_amount,
        label: `⫸ Tên: ${agency.name} ⇿ Địa chỉ: ${agency.address}`
      })
    })
    await Promise.all(getDetailAgencies)
    console.log("agencies", agencies)
    setRowData([...agencies])
    setCount(agencies.length)
  }, [store.agenciesBasic])

  const dispatch = useDispatch()
  indexSTT.current = 0
  useMemo(() => {
    setLengthData(rowData.filter(item => (item.id === -1 || (item.id !== -2 && (item.total_number <= 0 || item.total_number === '')))).length)
    dispatch(
      setAgencies(
        {
          agencies: rowData.filter(item => (item.id !== -1 && item.id !== -2))
        }
      )
    )
  
  }, [rowData])

  const increaseCount = () => {
    setCount(count + 1)
    setRowData([
      ...rowData,
      {
        id: -1,
        total_number: "",
        label: ''
      }
    ])  
  }

  const deleteForm = (e, i) => {
    e.preventDefault()
    const slideDownWrapper = e.target.closest('.react-slidedown'),
      form = e.target.closest('form')
    if (slideDownWrapper) {
      slideDownWrapper.remove()
    } else {
      form.remove()
    }

    const tmp = []
    Object.assign(tmp, [...rowData])
    tmp[i] = {
      ...tmp[i],
      id: -2
    }
    setRowData([...tmp])
  }

  const handleOnChangeSelect = (e, i) => {
    const tmp = []
    Object.assign(tmp, [...rowData])
    tmp[i] = {
      ...tmp[i],
      id: e.value,
      label: e.label
    }
    setRowData([...tmp])
  }

  const handleOnChangeInput = (value, i) => {
    console.log(value, i)
    const tmp = []
    Object.assign(tmp, [...rowData])
    tmp[i] = {
      ...tmp[i],
      total_number: value
    }
    setRowData([...tmp])
  }

  return (
    <Fragment>
       <Repeater count={count}>
          {i => {
            const Tag = i === 0 ? 'div' : SlideDown
            indexSTT.current += (rowData[i].id > -2) ? 1 : 0
            return (
              <Tag key={i}>
                <Form>
                  <b>{ indexSTT.current}</b>
                  <Row className='justify-content-between align-items-center'>
                    <Col md={8} className='mb-md-0 mb-1'>
                      <SelectEditReactCST rowData={rowData} index={i} defaultV={{value: rowData[i].id, label: rowData[i].label}}  onChange={(value) => handleOnChangeSelect(value, i)}/>
                    </Col>
                    <Col md={4} className='mb-md-0 mb-1'>
                      <Label className='form-label'>
                        Số lượng giải phân bổ
                      </Label>
                      <Input value={rowData[i].total_number} type='number' onChange={(e) => handleOnChangeInput(e.target.value, i)}/>
                    </Col>
                    <Col md={4}>
                      <Button color='danger' className='text-nowrap px-1 mt-2' onClick={(e) => deleteForm(e, i)} outline>
                        <X size={14} className='me-50' />
                        <span>Xóa</span>
                      </Button>
                    </Col>
                    <Col sm={12}>
                      <hr />
                    </Col>
                  </Row>
                </Form>
              </Tag>
            )
          }}
        </Repeater>
        <Button className='btn-icon' color='primary' onClick={increaseCount}>
          <Plus size={14} />
          <span className='align-middle ms-25'>Thêm đại lý</span>
        </Button>
    </Fragment>
  )
}

export default FormRepeaterAgenciesEditCST
