// ** React Imports
import { Fragment, useEffect } from 'react'

// ** Reactstrap Imports
import {
  Card,
  Row,
  Col,
  Modal,
  Input,
  Label,
  Button,
  CardBody,
  CardText,
  CardTitle,
  ModalBody,
  ModalHeader,
  FormFeedback
} from 'reactstrap'

// ** Third Party Components
import Select from 'react-select'
import { User, Check, X } from 'react-feather'
import FormAddCampain from '../FormAddCampainComponent'
import { useDispatch } from 'react-redux'
import { getAgencies, setDateEnd, setDateStart } from '../FormAddCampainComponent/store'
// import FormAddAgent from '../'


const ModaAddCampain = (props) => {
  const {isShow, setIsShow} = props
  // const [isEditFunc, setIsEditFunc] = useState(false)
  const dispatch = useDispatch()
  useEffect(() => {
    dispatch(
      getAgencies()
    )
    // const date = new Date(
    //   new Date(
    //     new Date().toLocaleString('vi-VN', {
    //       timeZone: 'Asia/Ho_Chi_Minh'
    //   }))
    // )

    const date = new Date()
    const date2 = new Date()

    dispatch(
      setDateStart(new Date(`${date.getFullYear()}-${date.getMonth() + 1}-${date.getDate()} ${`0${date.getHours()}`.slice(-2)}:${`0${date.getMinutes()}`.slice(-2)}`))
    )

    date2.setDate(date2.getDate() + 1)
    dispatch(
      setDateEnd(new Date(`${date2.getFullYear()}-${date2.getMonth() + 1}-${date2.getDate()} ${`0${date.getHours()}`.slice(-2)}:${`0${date.getMinutes()}`.slice(-2)}`))
    )
  }, [isShow])
  
  return (
    <Fragment>
      <Modal isOpen={isShow} className='modal-dialog-centered modal-fullscreen'>
        <ModalHeader className='bg-transparent' toggle={() => setIsShow(!isShow)}></ModalHeader>
        <ModalBody className='px-sm-5 mx-50 pb-5'>
          <div className='text-center mb-2'>
            <h1 className='mb-1 fw-bold'>Thêm chiến dịch mới</h1>
            <p>Bạn có thể thêm một chiến dịch mới ở đây.</p>
          </div>
          <Row className='gy-1 pt-75'>
            <Col sm="12">
              <FormAddCampain showModalParent={(value) => setIsShow(value)} />
            </Col>
            <Col xs={12} className='text-center mt-2 pt-50'>
              {/* <Button className='me-1' color={(!isEditFunc) ? 'primary' : 'success'} onClick={() => setIsEditFunc(!isEditFunc)}>
                {(!isEditFunc) ? 'Chỉnh sửa' : 'Lưu lại' }
              </Button> */}
              <Button type='reset' color='secondary' outline onClick={() => setIsShow(false)}>
                Trở lại
              </Button>
            </Col>
          </Row>
        </ModalBody>
      </Modal>
    </Fragment>
  )
}

export default ModaAddCampain
