// ** Reactstrap Imports
import { Card, CardHeader, CardTitle, CardBody, CardText, Input, Label } from 'reactstrap'

const TextareaCST = ({setValue, width, defaultV}) => {
  return (
    <div className='form-floating mt-2'>
      <Input
        value={defaultV}
        type='textarea'
        name='text'
        id='floating-textarea'
        placeholder='Floating Label'
        style={{ minHeight: (width === undefined || width === null) ? '100px' : width}}
        onChange={(e) => setValue(e.target.value)}
      />
      <Label className='form-label' for='floating-textarea'>
        Mô tả
      </Label>
    </div>
  )
}
export default TextareaCST
