// ** React Imports
import { Fragment, useRef, useMemo } from 'react'

// ** Icons Imports
import { ArrowLeft, ArrowRight } from 'react-feather'
import { useDispatch, useSelector } from 'react-redux'

// ** Reactstrap Imports
import { Label, Row, Col, Input, Form, Button, FormFeedback } from 'reactstrap'
import PickerDateForEdit from '../../PickerDateForEdit/index.js'
import TextareaCST from '../../TextAreaComponent/index.js'
import { setDateEnd, setDateStart, setDescription, setName } from '../store/index.js'
// import {  setDescription, setName } from '../store/index.js'

const CampaignInfo = ({ stepper }) => {
  const dispatch = useDispatch()
  const store = useSelector(state => state.formEditCampaign)

  const handleDispatchName = (e) => {
    dispatch(
      setName(e.target.value)
    )
  }
  const handleDispatchDateStart = (value) => {
    dispatch(
      setDateStart((value !== null) ? value : null)
    )
  }

  const handleDispatchDateEnd = (value) => {
    console.log(value)
    dispatch(
      setDateEnd(value)
    )
  }
  const handleDispatchDescription = (value) => {
    dispatch(
      setDescription(value)
    )
  }

  const handleSubmit = (e) => {
    e.preventDefault()
    let check = true
    if (store.name === null || store.name === '') {
      check = false
      dispatch(
        setName('')
      )
    }

    if (store.dateStart === undefined || store.dateEnd === undefined || store.dateStart === null || store.dateEnd === null ||  store.dateStart.getTime() >= store.dateEnd.getTime()) {
      check = false
    }

    if (store.description === null) dispatch(
        setDescription('')
      )

    if (check) stepper.next()
  }

  const dateStart = useRef()
  const dateEnd = useRef()
  useMemo(() => {
    dateStart.current = new Date(`${store.dateStart.getFullYear()}-${`0${store.dateStart.getMonth() + 1}`.slice(-2)}-${`0${store.dateStart.getDate()}`.slice(-2)} ${`0${store.dateStart.getHours()}`.slice(-2)}:${`0${store.dateStart.getMinutes()}`.slice(-2)}`)
    dateEnd.current = new Date(`${store.dateEnd.getFullYear()}-${`0${store.dateEnd.getMonth() + 1}`.slice(-2)}-${`0${store.dateEnd.getDate()}`.slice(-2)} ${`0${store.dateStart.getHours()}`.slice(-2)}:${`0${store.dateStart.getMinutes()}`.slice(-2)}`)
  }, [store.dateStart, store.dateEnd])
  // const dateEnd = new Date(`${`0${store.dateEnd.getDate()}`.slice(-2)}-${`0${store.dateEnd.getMonth() + 1}`.slice(-2)}-${store.dateEnd.getFullYear()}`)
  // console.log("dateStart", dateStart)
  // console.log("dateEnd", dateEnd)
  return (
    <Fragment>
      <div className='content-header'>
        <h5 className='mb-0'>THÔNG TIN CHUNG</h5>
        <small className='text-muted'>...</small>
      </div>
      <Form onSubmit={e => handleSubmit(e)}>
        <Row>
          <Col md='6' className='mb-1'>
            <Label className='form-label'>
              Tên chiến dịch
            </Label>
            <Input type='text' defaultValue={store.name} invalid={store.name === ''} value={store.name} onChange={(e) => handleDispatchName(e)}/>
            {store.name === '' && <FormFeedback>Bạn chưa nhập tên chiến dịch</FormFeedback>}
          </Col>
          <Col md='6' className='mb-1'>
            <Label className='form-label'>
              Ngày bắt đầu
            </Label>
            <PickerDateForEdit defaultV={dateStart.current} invalid={store.dateStart.getTime() >= store.dateEnd?.getTime()} setValue={(value) => handleDispatchDateStart(value)}/>
            {store.dateStart !== undefined && store.dateStart !== null && (store.dateStart.getTime() >= store.dateEnd.getTime()) && <FormFeedback>Ngày bắt đầu phải nhỏ hơn ngày kết thúc</FormFeedback>}
            {(store.dateStart === undefined || store.dateStart === null) && <FormFeedback>Ngày bắt đầu không được để tróng</FormFeedback>}
          </Col>
          <Col md='6' className='mb-1'>
            <Label className='form-label'>
              Ngày kết thúc
            </Label>
            <PickerDateForEdit defaultV={dateEnd.current} invalid={store.dateStart?.getTime() >= store.dateEnd?.getTime()} setValue={(value) => handleDispatchDateEnd(value)}/>
            {(store.dateEnd !== undefined && store.dateEnd !== null && store.dateStart.getTime() >= store.dateEnd.getTime()) && <FormFeedback>Ngày kết thúc phải lớn hơn ngày bắt dâu</FormFeedback>}
            {(store.dateEnd === undefined && store.dateEnd === null) && <FormFeedback>Ngày kết thúc không được để trống</FormFeedback>}
          </Col>
          <Col md='6' className='mb-1'>
            <TextareaCST defaultV={store.description} setValue={(value) => handleDispatchDescription(value)}/>
          </Col>
        </Row>
        <div className='d-flex justify-content-between'>
          <Button color='secondary' className='btn-prev' outline disabled>
            <ArrowLeft size={14} className='align-middle me-sm-25 me-0'></ArrowLeft>
            <span className='align-middle d-sm-inline-block d-none'>Trước</span>
          </Button>
          <Button color='primary' className='btn-next' type='submit'>
            <span className='align-middle d-sm-inline-block d-none'>Tiếp theo</span>
            <ArrowRight size={14} className='align-middle ms-sm-25 ms-0'></ArrowRight>
          </Button>
        </div>
      </Form>
    </Fragment>
  )
}

export default CampaignInfo
