import { Button } from "reactstrap"
import { Fragment, useState } from "react"
import { ArrowLeft, ArrowRight } from "react-feather"
import FormRepeaterAwardsCST from "../../FormRepeaterAwardsComponent"
import { useSelector } from "react-redux"
import toast from "react-hot-toast"
import FormRepeaterAwardsEditCST from "../../FormRepeaterAwardsEditComponent"

const AwardsCampaign = ({stepper}) => {
  const [checkValid, setCheckValid] = useState(false)
  const [callback, setCallBack] = useState()
  const store = useSelector(state => state.formEditCampaign)

  const handleNext = () => {
    if (checkValid) {
      toast.error("Vui lòng nhập đầy đủ thông tin các giải thưởng.")
      console.log(callback)
      return
    }

    let totalRewards = 0
    let totalAgencies = 0
    store.agencies.map(item => {
      totalAgencies += Number.parseInt(item.total_number)
    })
    store.rewards.map(item => {
      totalRewards += Number.parseInt(item.total_number)
    })

    if (totalAgencies > totalRewards) {
      toast.error(`Tổng số lượng phần thưởng phải tối thiểu ${totalAgencies} (lớn hơn hoặc bằng tổng số lượng phân bố cho các đại lý)`)
      return
    }

    stepper.next()
    // dispatch(
    //   updateCampaign()
    // )
    // .then(() => {
    //   dispatch(
    //     reloadTable({
    //       getData: (value) => dispatch(getData(value))
    //     })
    //   )
    //   showModalParent(false)
    // })
  }

  const callBackShowValid = (callback) => {
    console.log(callback)
    setCallBack(callback)
  }

  return (
    <Fragment> 
       <div className='content-header'>
        <h5 className='mb-0'>Danh mục giải thưởng trong chiến dịch</h5>
        <small className='text-muted'>...</small>
      </div>
      <FormRepeaterAwardsEditCST setCheckValid={(value) => setCheckValid(value)} callBackShowValid={(value) => callBackShowValid(value)}/>
      <div className='d-flex justify-content-between mt-1'>
          <Button color='secondary' className='btn-prev' onClick={() => stepper.previous()} outline>
            <ArrowLeft size={14} className='align-middle me-sm-25 me-0'></ArrowLeft>
            <span className='align-middle d-sm-inline-block d-none'>Trước</span>
          </Button>
          <Button color='primary' className='btn-next' onClick={() => handleNext()}>
            <span className='align-middle d-sm-inline-block d-none'>Tiếp theo</span>
            <ArrowRight size={14} className='align-middle ms-sm-25 ms-0'></ArrowRight>
          </Button>
      </div>
    </Fragment>
  )
}

export default AwardsCampaign