const ExportRewardLinks = () => {
  const store = useSelector(state => state.formShowCampaign)
  const {arrCodeUsed} = store
  const {arrCodeNotUsed} = store
  // ** Ref
  const tableRef = useRef()

  // ** States
  const [data, setData] = useState([])
  const [value, setValue] = useState('')
  const [modal, setModal] = useState(false)
  const [fileName, setFileName] = useState('')
  const [filteredData, setFilteredData] = useState([])
  const [fileFormat, setFileFormat] = useState('xlsx')
  const [countUsed, setCountUsed] = useState(0)
  const [countNotUsed, setCountNotUsed] = useState(0)

  useEffect(() => {
    const arr = []
    let stt = 0
    arrCodeNotUsed.map(code => {
      stt++
      arr.push({
        stt,
        link: `${jwtConfig.endPointLottery}?code=${btoa(code.RewardLinks.code)}`,
        code: code.RewardLinks.code,
        nameAgency: code.Agencies.name,
        comment: 'Chưa sử dụng'
      })
    })
    setCountNotUsed(stt)
    const tmp = stt
    arrCodeUsed.map(code => {
      stt++
      arr.push({
        stt,
        link: `${jwtConfig.endPointLottery}?code=${btoa(code.RewardLinks.code)}`,
        code: code.RewardLinks.code,
        nameAgency: code.Agencies.name,
        comment: 'Đã sử dụng'
      })
    })
    setCountUsed(stt - tmp)
    setData([...arr])
  }, [store])
  

  const toggleModal = () => {
    setModal(!modal)
  }

  const handleFilter = e => {
    const dataArr = data
    let filteredData = []
    const value = e.target.value
    setValue(value)
    if (value.length) {
      filteredData = dataArr.filter(col => {
        const startsWithCondition =
          col.link.toLowerCase().startsWith(value.toLowerCase()) ||
          col.code.toLowerCase().startsWith(value.toLowerCase()) ||
          col.comment.toLowerCase().startsWith(value.toLowerCase())

        const includesCondition =
          col.link.toLowerCase().includes(value.toLowerCase()) ||
          col.code.toLowerCase().includes(value.toLowerCase()) ||
          col.comment.toLowerCase().includes(value.toLowerCase())

        if (startsWithCondition) return startsWithCondition
        else if (!startsWithCondition && includesCondition) return includesCondition
        else return null
      })
      setFilteredData(filteredData)
      setValue(value)
    }
  }

  const handleExport = () => {
    toggleModal()
    const bookType = fileFormat
    const wb = utils.table_to_book(tableRef.current, { sheet: 'Sheet JS' })
    const wbout = write(wb, { bookType, bookSST: true, type: 'binary' })

    const s2ab = s => {
      const buf = new ArrayBuffer(s.length)
      const view = new Uint8Array(buf)
      for (let i = 0; i < s.length; i++) view[i] = s.charCodeAt(i) & 0xff
      return buf
    }
    const file = fileName.length ? `${fileName}.${fileFormat}` : `excel-sheet.${fileFormat}`

    return FileSaver.saveAs(new Blob([s2ab(wbout)], { type: 'application/octet-stream' }), file)
  }

  const array = value ? filteredData : data
  const renderTableData = array.map(col => {
    return (
      <tr key={col.id}>
        <td>{col.stt}</td>
        <td>{col.link}</td>
        <td>{col.code}</td>
        <td>{col.nameAgency}</td>
        <td className={(col.comment === "Chưa sử dụng" ? 'text-danger' : 'text-success')}>{col.comment}</td>
      </tr>
    )
  })

  return (
    <Fragment>
      <ExtensionsHeader
        title='XLSX'
        subTitle=''
        link='https://github.com/SheetJS/sheetjs'
      />
      <Row className='export-component'>
        <Col sm='12'>
          <Card>
            <CardBody className='pb-0'>
              <div className='d-flex justify-content-between flex-wrap flex-sm-row flex-column'>
                <Button color='primary' onClick={() => toggleModal()}>
                  Xuất
                </Button>
                Tổng cộng: {countNotUsed + countUsed}, đã dùng: {countUsed}
                <div className='d-flex align-items-center justify-content-end mt-sm-0 mt-1'>
                  <Label for='search-input' className='me-1 text-nowrap'>
                    Tìm kiếm
                  </Label>
                  <Input id='search-input' bsSize='sm' type='text' value={value} onChange={e => handleFilter(e)} />
                </div>
              </div>
            </CardBody>
            <Table innerRef={tableRef} className='table-hover-animation mt-2' responsive>
              <thead>
                <tr>
                  <th>STT</th>
                  <th>Liên kết</th>
                  <th>Mã tham gia</th>
                  <th>Tên đại lý</th>
                  <th>Tình trạng</th>
                </tr>
              </thead>
              <tbody>{renderTableData}</tbody>
            </Table>
          </Card>
        </Col>
      </Row>
      <Modal
        isOpen={modal}
        toggle={() => toggleModal()}
        className='modal-dialog-centered'
        onClosed={() => setFileName('')}
      >
        <ModalHeader toggle={() => toggleModal()}>Xuất sang Excel</ModalHeader>
        <ModalBody>
          <div className='mb-2'>
            <Input
              type='text'
              value={fileName}
              onChange={e => setFileName(e.target.value)}
              placeholder='Nhập tên file'
            />
          </div>
          <div>
            <Input
              type='select'
              id='selectFileFormat'
              name='customSelect'
              value={fileFormat}
              onChange={e => setFileFormat(e.target.value)}
            >
              <option>xlsx</option>
              <option>csv</option>
              <option>txt</option>
            </Input>
          </div>
        </ModalBody>
        <ModalFooter>
          <Button color='primary' onClick={() => handleExport()}>
            Xuất
          </Button>
          <Button color='flat-danger' onClick={() => toggleModal()}>
            Đóng
          </Button>
        </ModalFooter>
      </Modal>
    </Fragment>
  )
}

