// ** React Imports
import { useRef, useState } from 'react'

// ** Custom Components
import Wizard from '@components/wizard'

// ** Steps
import Address from './steps/Address'
import SocialLinks from './steps/SocialLinks'
import PersonalInfo from './steps/PersonalInfo'
import AccountDetails from './steps/AccountDetails'
import CampaignInfo from './steps/CampaignInfo'
import CoverCampaign from './steps/CoverCampaign'
import AgentsCampaign from './steps/AgentsCampaign'
import AwardsCampaign from './steps/AwardsCampaign'
import CoverRotation from './steps/CoverRotation'
import SpecialAwardsCampaign from './steps/SpecicalAwardCampaign'

const FormEditCampain = ({showModalParent}) => {
  // ** Ref
  const ref = useRef(null)

  // ** State
  const [stepper, setStepper] = useState(null)

  const steps = [
    {
      id: 'campaign-info',
      title: 'Thông tin chung',
      subtitle: 'Thiết lập thông tin chiến dịch',
      content: <CampaignInfo stepper={stepper} type='wizard-vertical' />
    },
    {
      id: 'cover-campaign',
      title: 'Ảnh chiến dịch',
      subtitle: 'Thiết lập ảnh chiến dịch',
      content: <CoverCampaign stepper={stepper} type='wizard-vertical' />
    },
    {
      id: 'cover-rotaion',
      title: 'Ảnh vòng quay',
      subtitle: 'Thiết lập ảnh vòng quay',
      content: <CoverRotation stepper={stepper} type='wizard-vertical' />
    },
    {
      id: 'agents-campaign',
      title: 'Đại lý trong chiến dịch',
      subtitle: 'Chọn danh mục đại lý tham gia',
      content: <AgentsCampaign stepper={stepper} type='wizard-vertical' />
    },
    {
      id: 'awards-campaign',
      title: 'Danh mục giải thưởng',
      subtitle: 'Chọn danh mục giải thưởng',
      content: <AwardsCampaign stepper={stepper} showModalParent={showModalParent} type='wizard-vertical' />
    },
    {
      id: 'spec-awards-campaign',
      title: 'Danh mục giải đặc biệt',
      subtitle: 'Chọn danh mục giải đặc biệt',
      content: <SpecialAwardsCampaign stepper={stepper} showModalParent={showModalParent} type='wizard-vertical' />
    }

  ]

  return (
    <div className='vertical-wizard'>
      <Wizard
        type='modern-vertical'
        ref={ref}
        steps={steps}
        options={{
          linear: true
        }}
        instance={el => setStepper(el)}
      />
    </div>
  )
}

export default FormEditCampain
