// ** React Imports
import { useRef, useState } from 'react'

// ** Custom Components
import Wizard from '@components/wizard'

// ** Steps
import Address from './steps/Address'
import SocialLinks from './steps/SocialLinks'
import PersonalInfo from './steps/PersonalInfo'
import AccountDetails from './steps/AccountDetails'
import CampaignInfo from './steps/CampaignInfo'
import CoverCampaign from './steps/CoverCampaign'
import AgentsCampaign from './steps/AgentsCampaign'
import AwardsCampaign from './steps/AwardsCampaign'
import RotationCampaign from './steps/RotationCampaign'
import UsersCampaign from './steps/UsersCampaign'
import SpecialAwardsCampaign from './steps/SpecicalAwardCampaign'
import RewardLinksCampaign from './steps/RewardLinkssCampaign'

const FormShowCampain = () => {
  // ** Ref
  const ref = useRef(null)

  // ** State
  const [stepper, setStepper] = useState(null)

  const steps = [
    {
      id: 'campaign-info',
      title: 'Thông tin chung',
      subtitle: 'Thông tin chiến dịch',
      content: <CampaignInfo stepper={stepper} type='wizard-vertical' />
    },
    {
      id: 'cover-campaign',
      title: 'Ảnh chiến dịch',
      subtitle: 'Hình ảnh liên quan đến chiến dịch',
      content: <CoverCampaign stepper={stepper} type='wizard-vertical' />
    },
    {
      id: 'rotaion-campaign',
      title: 'Ảnh vòng quay',
      subtitle: 'Ảnh vòng quay may mắn',
      content: <RotationCampaign stepper={stepper} type='wizard-vertical' />
    },
    {
      id: 'agents-campaign',
      title: 'Đại lý trong chiến dịch',
      subtitle: 'Danh mục đại lý tham gia',
      content: <AgentsCampaign stepper={stepper} type='wizard-vertical' />
    },
    {
      id: 'awards-campaign',
      title: 'Danh mục giải thưởng',
      subtitle: 'Danh mục các giải thưởng',
      content: <AwardsCampaign stepper={stepper} type='wizard-vertical' />
    },
    {
      id: 'users-campaign',
      title: 'Danh mục khách hàng',
      subtitle: 'Danh mục các khách hàng tham gia',
      content: <UsersCampaign stepper={stepper} type='wizard-vertical' />
    },
    {
      id: 'link-awards-campaign',
      title: 'Danh mục liên kết quay thưởng',
      subtitle: 'Danh mục liên kết quay thưởng',
      content: <RewardLinksCampaign stepper={stepper} type='wizard-vertical' />
    },
    {
      id: 'spec-awards-campaign',
      title: 'Danh mục giải đặc biệt',
      subtitle: 'Danh mục giải đặc biệt',
      content: <SpecialAwardsCampaign stepper={stepper} type='wizard-vertical' />
    }
    // ,
    // {
    //   id: 'account-info',
    //   title: 'Personal Info',
    //   subtitle: 'Add Personal Info',
    //   content: <PersonalInfo stepper={stepper} type='wizard-vertical' />
    // }
  ]

  return (
    <div className='vertical-wizard' style={{
      height: 'fit-content'
    }}>
      <Wizard
        type='modern-vertical'
        ref={ref}
        steps={steps}
        options={{
          linear: false
        }}
        instance={el => setStepper(el)}
      />
    </div>
  )
}

export default FormShowCampain
