// ** React Imports
import { Fragment, useEffect, useState } from 'react'

// ** Icons Imports
import { ArrowLeft, ArrowRight } from 'react-feather'
import { useDispatch, useSelector } from 'react-redux'
import Select from 'react-select'
import { selectThemeColors } from '@utils'
import classNames from 'classnames'
// ** Reactstrap Imports
import { Label, Row, Col, Input, Form, Button, FormFeedback } from 'reactstrap'
import { setPercent, setSpecAwards, updateCampaign } from "../store"
import { getData, reloadTable } from "../../TableComponent/store"
import toast from 'react-hot-toast'
// import {  setDescription, setName } from '../store/index.js'

const SpecialAwardsCampaign = ({ stepper, showModalParent }) => {
  const dispatch = useDispatch()
  const store = useSelector(state => state.formEditCampaign)
  const [specAwards, setSpecAwardsState] = useState([])
  const [awards, setAwards] = useState()
  const [percent, setPercentState] = useState()

  useEffect(() => {
    setAwards(
      store.rewards.map(item => ({
        value: item.name,
        label: item.name
      }))
    )
  }, [store.rewards])

  useEffect(() => {
    setPercentState(store.percent)
  }, [store.percent])

  const handleSpecAwardsChange = (e) => {
    setSpecAwardsState(e)
    dispatch(
      setSpecAwards({
        specAwards: e
      })
    )
  }

  useEffect(() => {
  }, [specAwards])

  const handleSubmit = (e) => {
    e.preventDefault()
    
    if (((Number.parseFloat(store.percent) <= 0 || Number.parseFloat(store.percent) >= 100)) || store.specAwards.length <= 0 || store.percent === '') {
      toast.error("Vui lòng kiểm tra lại các giải đặc biệt và tỷ lệ bắt đầu")
      return
    }

    dispatch(
      updateCampaign()
    )
    .then(() => {
      dispatch(
        reloadTable({
          getData: (value) => dispatch(getData(value))
        })
      )
      showModalParent(false)
    })
  }
  
  const handleChangePercent = (e) => {
    setPercentState(e.target.value)
    dispatch(
      setPercent({
        percent: e.target.value
      })
    )
  }

  return (
    <Fragment>
      <div className='content-header'>
        <h5 className='mb-0'>THÔNG TIN CHUNG</h5>
        <small className='text-muted'>...</small>
      </div>
      <Form onSubmit={e => handleSubmit(e)}>
        <Row>
          <Col md='6' className='mb-1'>
            <Label className='form-label'>
              <span>{"Tỷ lệ để bắt đầu (0 < % < 100)"}</span>
            </Label>
            <Input type='number' invalid={(percent === "" || Number.parseFloat(store.percent) <= 0 || Number.parseFloat(store.percent) >= 100)} value={percent} onChange={(e) => {
              handleChangePercent(e)
            }}/>
            { ((percent === "" || Number.parseFloat(store.percent) <= 0 || Number.parseFloat(store.percent) >= 100)) && <FormFeedback>Tỷ lệ phần trăm phải là số {"(0 < % < 100)"}</FormFeedback>}
          </Col>
          <Col md='6' className='mb-1'>
            <Label className='form-label'>Chọn giải đặc biệt</Label>
            <Select
              isClearable={false}
              theme={selectThemeColors}
              value={store.specAwards}
              placeholder={"Chọn giải đặc biệt"}
              isMulti
              name='colors'
              options={awards}
              className='react-select'
              classNamePrefix='select'
              onChange={(e) => handleSpecAwardsChange(e)}
              className={classNames('react-select', {'is-invalid': store.specAwards.length <= 0})}
            />
            {store.specAwards.length <= 0 && <FormFeedback>Bạn chưa chọn giải đặc biệt</FormFeedback>}
          </Col>
        </Row>
        <div className='d-flex justify-content-between'>
          <Button color='secondary' className='btn-prev' outline onClick={() => stepper.previous()}>
            <ArrowLeft size={14} className='align-middle me-sm-25 me-0'></ArrowLeft>
            <span className='align-middle d-sm-inline-block d-none'>Trước</span>
          </Button>
          <Button color='success' className='btn-next' type='submit'>
            <span className='align-middle d-sm-inline-block d-none'>Lưu chiến dịch</span>
            <ArrowRight size={14} className='align-middle ms-sm-25 ms-0'></ArrowRight>
          </Button>
        </div>
      </Form>
    </Fragment>
  )
}

export default SpecialAwardsCampaign
