// ** React Imports
import { Fragment, useState} from 'react'

// ** Reactstrap Imports
import { Label } from 'reactstrap'

// ** Third Party Components
import Flatpickr from 'react-flatpickr'

// ** Styles
import '@styles/react/libs/flatpickr/flatpickr.scss'
// import classNames from 'classnames'

const PickerDate = ({setValue, invalid, defaultV}) => {
  // ** State
  const [picker, setPicker] = useState(defaultV)
  const handleChangeDate = (date) => {
    if (date !== undefined && date !== null && date.length > 0) {
      setPicker(date)
      const datePine = new Date(date[0])
      setValue(new Date(`${datePine.getFullYear()}-${datePine.getMonth() + 1}-${datePine.getDate()} ${`0${datePine.getHours()}`.slice(-2)}:${`0${datePine.getMinutes()}`.slice(-2)}`))
    } else {
      const datePine = new Date()
      setPicker([datePine])
      setValue(new Date(`${datePine.getFullYear()}-${datePine.getMonth() + 1}-${datePine.getDate()} ${`0${datePine.getHours()}`.slice(-2)}:${`0${datePine.getMinutes()}`.slice(-2)}`))
    }
  }

  // useEffect(() => {
  //   setPicker(defaultV)
  // }, [defaultV])

  return (
    <Fragment>
      {/* <Label className='form-label' for='default-picker'>
        Default
      </Label> */}
      <Flatpickr className={`form-control ${(invalid === true) ? 'is-invalid' : ''} flatpickr-input`} 
        data-enable-time
        value={picker}
        onChange={date => handleChangeDate(date)} 
        id='default-picker'/>
    </Fragment>
  )
}

export default PickerDate
