import AvatarGroup from '@components/avatar-group'
import useJwt from '@src/auth/jwt/useJwt'
import { useState, useMemo } from 'react'

import { MoreVertical, Edit, Trash } from 'react-feather'
import { Table, Badge, UncontrolledDropdown, DropdownMenu, DropdownItem, DropdownToggle } from 'reactstrap'


const TableShowAgency = ({data}) => {
  const [dataR, setDataR] = useState([])
  useMemo(async () => {
    const data2 = []
    const arrData = data.map(async (item) => {
      const agency_campaign = await useJwt.getAgencyCampaign({
        id: item.agency_campaign_id
      })
      data2.push({
        ...item, 
        total_number: agency_campaign.data.reward_amount
      })
    })
    await Promise.all(arrData)
    setDataR(data2)
  }, [data])
  return (
    <Table responsive>
      <thead>
        <tr>
          <th>Mã đại lý</th>
          <th>Tên đại lý</th>
          <th>Email</th>
          <th>Điện thoại</th>
          <th>Địa chỉ</th>
          <th>Số giải phân bổ</th>
        </tr>
      </thead>
      <tbody>
        {
          (dataR !== null && dataR !== undefined) && dataR.map(item => (
            <tr>
              <td>
                <span className='align-middle fw-bold'>{item.id}</span>
              </td>
              <td>{item.name}</td>
              <td>
                {item.email}
              </td>
              <td>
                {item.phone}
              </td>
              <td>
                {item.address}
              </td>
              <td>
                {item.total_number}
              </td>
            </tr>
          ))
        }
      </tbody>
    </Table>
  )
}

export default TableShowAgency